SELECT *, SUM(balance) OVER w_recent AS running_sum_balance, AVG(balance) OVER w_recent AS running_avg_balance, MIN(balance) OVER w_recent AS running_min_balance, AVG(balance) OVER (PARTITION BY customer_id ORDER BY opened_date, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS balance_avg_5 FROM accounts WINDOW w_recent AS (PARTITION BY account_type ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
